'use strict';
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const figure=$('.system-figure');if(figure&&$('.diagram-mobile'))$('.diagram-mobile').append(figure.cloneNode(true));
// Unique SVG identifiers for the mobile copy.
const mobileFigure=$('.diagram-mobile svg');if(mobileFigure){mobileFigure.querySelector('#system-title').id='system-title-mobile';mobileFigure.setAttribute('aria-labelledby','system-title-mobile');mobileFigure.querySelector('#aura').id='aura-mobile';mobileFigure.querySelector('ellipse').setAttribute('fill','url(#aura-mobile)');}
if('IntersectionObserver' in window){document.documentElement.classList.add('js');const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>io.observe(e));const ctaIO=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('shine');ctaIO.unobserve(e.target)}}),{threshold:.5});$$('.cta').forEach(e=>ctaIO.observe(e));}
const originalTrack=$('.condition-track'); if(!reduced.matches){[...originalTrack.children].forEach(card=>{const clone=card.cloneNode(true);clone.classList.add('carousel-clone');clone.tabIndex=-1;clone.setAttribute('aria-hidden','true');originalTrack.append(clone)})}
const dialog=$('#condition-dialog'),conditionData=JSON.parse($('#condition-data').textContent);let previousFocus=null;
$$('[data-condition]').forEach(b=>b.addEventListener('click',()=>{previousFocus=b;const c=conditionData[Number(b.dataset.condition)];$('#dialog-title').textContent=c.title;$('#dialog-description').textContent=c.body;const photo=document.createElement('img');photo.src='assets/'+c.image;photo.alt='Cena de rotina ilustrativa.';$('.dialog-image').replaceChildren(photo);dialog.showModal();document.body.style.overflow='hidden';$('.dialog-close').focus();updateScroll();}));
function closeDialog(){dialog.close();}$('.dialog-close').addEventListener('click',closeDialog);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus({preventScroll:true});updateScroll()});
$('.compare-stage input').addEventListener('input',e=>$('.compare-stage').style.setProperty('--split',e.target.value+'%'));
const compare=$('.compare-stage');if(!reduced.matches){const ob=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){let start;const animate=t=>{start??=t;let progress=Math.min((t-start)/1000,1);const value=50+Math.sin(progress*Math.PI*2)*8;compare.style.setProperty('--split',value+'%');if(progress<1&&!compare.matches(':focus-within'))requestAnimationFrame(animate);else compare.style.setProperty('--split',compare.querySelector('input').value+'%')};requestAnimationFrame(animate);ob.disconnect()}},{threshold:.5});ob.observe(compare)}
const track=$('.condition-track'), toggle=$('.autoplay-toggle');let paused=reduced.matches,hovered=false,visible=false,direction=1,last=0,carry=0;
toggle.textContent=paused?'Reproduzir':'Pausar';toggle.addEventListener('click',()=>{paused=!paused;toggle.textContent=paused?'Reproduzir':'Pausar';toggle.setAttribute('aria-label',paused?'Retomar movimento das condições':'Pausar movimento das condições')});track.addEventListener('mouseenter',()=>hovered=true);track.addEventListener('mouseleave',()=>hovered=false);track.addEventListener('focusin',()=>hovered=true);track.addEventListener('focusout',()=>hovered=false);track.addEventListener('pointerdown',()=>{paused=true;toggle.textContent='Reproduzir';toggle.setAttribute('aria-label','Retomar movimento das condições')});new IntersectionObserver(e=>{visible=e[0].isIntersecting}).observe(track);
$$('[data-carousel]').forEach(b=>b.addEventListener('click',()=>{paused=true;toggle.textContent='Reproduzir';toggle.setAttribute('aria-label','Retomar movimento das condições');track.scrollBy({left:Number(b.dataset.carousel)*(track.clientWidth*.8),behavior:reduced.matches?'instant':'smooth'})}));
function carouselTick(t){if(last&&visible&&!paused&&!hovered&&!reduced.matches&&!dialog.open){let delta=Math.min(t-last,40)*.022;carry+=delta;if(carry>=1){const pixels=Math.floor(carry);track.scrollLeft+=pixels;carry-=pixels}const firstClone=track.querySelector('.carousel-clone');const cycle=firstClone?firstClone.offsetLeft-track.firstElementChild.offsetLeft:track.scrollWidth-track.clientWidth;if(cycle>0&&track.scrollLeft>=cycle)track.scrollLeft-=cycle}last=t;requestAnimationFrame(carouselTick)}requestAnimationFrame(carouselTick);
reduced.addEventListener('change',()=>{paused=reduced.matches;toggle.textContent=paused?'Reproduzir':'Pausar'});
$$('[data-strip]').forEach(b=>b.addEventListener('click',()=>$('.ticker').scrollBy({left:Number(b.dataset.strip)*250,behavior:'smooth'})));
const routine=$('.routine-grid');routine.addEventListener('scroll',()=>{const max=routine.scrollWidth-routine.clientWidth;const portion=max>0?routine.scrollLeft/max:0;$('.swipe-progress span').style.transform=`translateX(${portion*300}%)`},{passive:true});
let pending=false;function updateScroll(){const hero=$('.hero').getBoundingClientRect();const floating=$('.floating-wa');const anyCTA=$$('.cta').some(e=>{const r=e.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight&&r.width>0&&r.height>0});floating.hidden=hero.bottom>0||anyCTA||dialog.open;const timeline=$('.timeline'),r=timeline.getBoundingClientRect();const progress=Math.max(0,Math.min(100,(innerHeight*.62-r.top)/r.height*100));timeline.style.setProperty('--progress',progress+'%');$$('.journey-step').forEach(e=>e.classList.toggle('is-active',e.getBoundingClientRect().top<innerHeight*.62));pending=false}
addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(updateScroll)}},{passive:true});addEventListener('resize',updateScroll);updateScroll();
